const noteName=m=>{const n=pcName(m%12),adjust=n[0]==='C'&&n.includes('♭')&&m%12>=10?1:n[0]==='B'&&n.includes('♯')&&m%12<=1?-1:0;return n+(Math.floor(m/12)-1+adjust)}, uid=()=>crypto.randomUUID?.()||'n'+Date.now().toString(36)+Math.random().toString(36).slice(2), clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
