const templates={dream:{name:'Evening light',chords:[[0,'maj7'],[9,'m7'],[5,'maj7'],[7,'maj']]},minor:{name:'After hours',chords:[[9,'9'],[5,'maj7'],[0,'maj7'],[7,'maj']]},space:{name:'Open skies',chords:[[2,'sus2'],[9,'maj'],[11,'m7'],[7,'maj7']]}};
let state={version:1,name:'Evening light',bpm:72,bars:8,notes:[],chords:[],loop:true,transition:-.08,key:0,scale:'major',arrangementKey:0,autoVoiceLeading:true,loopStart:0,loopEnd:32,view:{beatWidth:0,rowH:18,follow:false,scrollLeft:0,scrollTop:340}}, history=[],redoHistory=[],selected=new Set(),tool='select',ctx,synth,playing=false,timer,startTime,runBpm,events=[],nextEvent=0,runLoop=true,drag=null,toastTimer,editChord=0;
function chordNotes(ch){return PadHarmony.validVoicing(ch,ch.voicing)?ch.voicing:PadHarmony.rootVoicing(ch)}
const degreePatterns={dream:[0,5,3,4],minor:[0,5,2,6],space:[0,4,5,3]};
function makeTemplate(key){state.notes=[];state.chords=[];if(key==='blank'){state.name='Untitled session';return}const t=templates[key],span=state.bars,palette=PadHarmony.diatonic(state.key,state.scale);state.name=t.name;state.arrangementKey=state.key;degreePatterns[key].forEach((degree,i)=>{const d=palette[degree],ch={id:uid(),root:d.root,quality:i===3?d.triad:d.seventh,inversion:0,start:i*span,length:span,transition:state.transition};state.chords.push(ch);for(const midi of chordNotes(ch))state.notes.push({id:uid(),midi,start:ch.start,length:ChordTiming.gateLength(ch),velocity:.8,chordId:ch.id})});if(state.autoVoiceLeading)smoothChords()}
function smoothChords(){const ordered=[...state.chords].sort((a,b)=>a.start-b.start),voicings=PadHarmony.voiceLead(ordered,state.loop);ordered.forEach((c,i)=>{c.voicing=voicings[i];const notes=state.notes.filter(n=>n.chordId===c.id).sort((a,b)=>a.midi-b.midi);if(notes.length===c.voicing.length)notes.forEach((n,j)=>n.midi=c.voicing[j])})}
if(options.project)state=validProject(options.project);else if(options.notes)state=validProject({...state,bars:options.bars||8,loopEnd:(options.bars||8)*4,notes:options.notes});else {state=validProject({...state,bars:options.bars??8,loopEnd:(options.bars??8)*4,notes:[],chords:[],name:'Untitled clip'});}
function validProject(p){if(!p||p.version!==1||(!Number.isInteger(p.bars)||p.bars<1||p.bars>128)||!Number.isFinite(p.bpm)||p.bpm<35||p.bpm>180||!Array.isArray(p.notes)||p.notes.length>512)throw Error('Invalid project');let notes=p.notes.map(n=>{if(!Number.isInteger(n.midi)||n.midi<36||n.midi>84||!Number.isFinite(n.start)||n.start<0||n.start>=p.bars*4||!Number.isFinite(n.length)||n.length<=0||n.start+n.length>p.bars*4+2.001||!Number.isFinite(n.velocity)||n.velocity<.1||n.velocity>1)throw Error('Invalid note');return {...n,id:uid()}});let chords=Array.isArray(p.chords)?p.chords.filter(c=>Number.isInteger(c.root)&&c.root>=0&&c.root<12&&Object.hasOwn(intervals,c.quality)&&[0,1,2].includes(c.inversion)&&Number.isFinite(c.start)&&c.start>=0&&Number.isFinite(c.length)&&c.length>0&&c.start+c.length<=p.bars*4).slice(0,64).map(c=>({...c,_inferOwnership:typeof c.id!=='string',id:typeof c.id==='string'?c.id:uid(),transition:clamp(Number.isFinite(c.transition)?c.transition:-.08,-2,2)})):[];for(const c of chords){if(!PadHarmony.validVoicing(c,c.voicing))delete c.voicing;for(const n of notes){if(c._inferOwnership&&!n.chordId&&Math.abs(n.start-c.start)<.001&&chordNotes(c).includes(n.midi))n.chordId=c.id}delete c._inferOwnership}const range=PadNavigation.loopRange(p.loopStart,p.loopEnd,p.bars*4);return {version:1,loopStart:range.start,loopEnd:range.end,view:PadNavigation.normalizeView(p.view),name:String(p.name||'Untitled session').slice(0,60),bpm:p.bpm,bars:p.bars,notes,chords,loop:p.loop!==false,transition:clamp(Number.isFinite(p.transition)?p.transition:-.08,-2,2),key:Number.isInteger(p.key)&&p.key>=0&&p.key<12?p.key:0,scale:Object.hasOwn(PadHarmony.scales,p.scale)?p.scale:'major',arrangementKey:Number.isInteger(p.arrangementKey)&&p.arrangementKey>=0&&p.arrangementKey<12?p.arrangementKey:0,autoVoiceLeading:p.autoVoiceLeading===true}}
function snapshot(){const {params,preset,view,...arrangement}=state;return {state:JSON.stringify(arrangement),selection:[...selected]}}
function stash(){history.push(snapshot());if(history.length>100)history.shift();redoHistory=[];if($('undo'))$('undo').disabled=false;if($('redo'))$('redo').disabled=true}
function restoreEdit(entry){stop();velocityGesture=false;state={...state,...JSON.parse(entry.state)};selected=new Set(entry.selection.filter(id=>state.notes.some(n=>n.id===id)));refresh();persist()}
function undoEdit(){if(!history.length)return;redoHistory.push(snapshot());restoreEdit(history.pop())}
function redoEdit(){if(!redoHistory.length)return;history.push(snapshot());restoreEdit(redoHistory.pop())}

function persist(){ if(destroyed)return; $('saveStatus').textContent='JSON project ready'; emit('change',JSON.parse(JSON.stringify(state))); }
